package com.lendup.reservas.config.security;
import com.lendup.reservas.application.exception.ForbiddenException; import com.lendup.reservas.application.port.out.IdentidadPort; import java.util.UUID; import org.springframework.security.core.Authentication; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component;
@Component public class ActorContext { private final IdentidadPort identidad; public ActorContext(IdentidadPort identidad){this.identidad=identidad;} public UUID userId(){Authentication a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!a.isAuthenticated())throw new ForbiddenException("Identidad no autenticada");return identidad.resolverUsuarioId(a.getName());} public boolean administrator(){Authentication a=SecurityContextHolder.getContext().getAuthentication();return a!=null&&a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMINISTRADOR"));} }
